        ru: 'Когда товар не подходит, говори: «I would like to return this» — я хотел бы вернуть это. Или: «I would like to exchange this» — обменять. Слово «would like» — вежливая просьба, всегда работает в магазине.',
        uk: 'Коли товар не підходить, кажи: «I would like to return this» — я хотів би повернути це. Або: «I would like to exchange this» — обміняти. Слово «would like» — ввічливе прохання, завжди працює в магазині.',
